// Classify each uploaded file against the fixed input-type list from BRD section 6.
// Mandatory: completed_audit_working_file, kickoff_deck.
// Optional: process_understanding, audit_notification, analysis_sheet, supporting_evidence.
const files = $input.all();
const classified = files.map(f => ({
  json: {
    engagement_id: $('When Executed by Orchestrator').first().json.engagement_id,
    doc_type: f.json.formFieldName, // mapped from the form's named upload slots
    file_ref: f.binary?.data?.fileName || f.json.fileRef
  }
}));
return classified;

// Gap flagging (FR-23): record which optional inputs are missing so the report
// can surface this explicitly rather than silently proceeding.
const required = ['completed_audit_working_file', 'kickoff_deck'];
const optional = ['process_understanding', 'audit_notification', 'analysis_sheet'];
const present = new Set($input.all().map(i => i.json.doc_type));
const missingRequired = required.filter(t => !present.has(t));
if (missingRequired.length) {
  throw new Error('Missing mandatory input(s): ' + missingRequired.join(', '));
}
const gaps = optional.filter(t => !present.has(t));
return [{ json: { input_gaps: gaps } }];
